package com.nosferatu.divinemachinerylegacy.proxy;
import com.nosferatu.divinemachinerylegacy.DivineMachineryLegacy;import com.nosferatu.divinemachinerylegacy.block.*;import com.nosferatu.divinemachinerylegacy.client.render.*;import com.nosferatu.divinemachinerylegacy.entity.EntityTieredManaSpark;import com.nosferatu.divinemachinerylegacy.gui.*;import com.nosferatu.divinemachinerylegacy.tile.*;import cpw.mods.fml.client.registry.RenderingRegistry;import cpw.mods.fml.relauncher.Side;import cpw.mods.fml.relauncher.SideOnly;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.tileentity.TileEntity;import net.minecraft.world.World;
@SideOnly(Side.CLIENT)public class ClientProxy extends CommonProxy{
 @Override public void registerRenderers(){int r=RenderingRegistry.getNextAvailableRenderId();BlockMechanicalRunicAltar.setRenderId(r);RenderingRegistry.registerBlockHandler(new RenderMechanicalRunicAltar(r));int p=RenderingRegistry.getNextAvailableRenderId();BlockMechanicalManaPool.setRenderId(p);RenderingRegistry.registerBlockHandler(new RenderMechanicalManaPool(p));int a=RenderingRegistry.getNextAvailableRenderId();BlockMechanicalApothecary.setRenderId(a);RenderingRegistry.registerBlockHandler(new RenderMechanicalApothecary(a));int d=RenderingRegistry.getNextAvailableRenderId();BlockMechanicalDaisy.setRenderId(d);RenderingRegistry.registerBlockHandler(new RenderMechanicalDaisy(d));RenderingRegistry.registerEntityRenderingHandler(EntityTieredManaSpark.class,new RenderTieredManaSpark());}
 @Override public Object getClientGuiElement(int id,EntityPlayer p,World w,int x,int y,int z){TileEntity te=w.getTileEntity(x,y,z);if(id==DivineMachineryLegacy.GUI_RUNIC_ALTAR&&te instanceof TileMechanicalRunicAltar)return new GuiMechanicalRunicAltar(p.inventory,(TileMechanicalRunicAltar)te);if(id==DivineMachineryLegacy.GUI_MANA_POOL&&te instanceof TileMechanicalManaPool)return new GuiMechanicalManaPool(p.inventory,(TileMechanicalManaPool)te);if(id==DivineMachineryLegacy.GUI_APOTHECARY&&te instanceof TileMechanicalApothecary)return new GuiMechanicalApothecary(p.inventory,(TileMechanicalApothecary)te);if(id==DivineMachineryLegacy.GUI_DAISY&&te instanceof TileMechanicalDaisy)return new GuiMechanicalDaisy(p.inventory,(TileMechanicalDaisy)te);return null;}}
